from pathlib import Path
ROOT=Path("project")
def write(rel, text):
    p=ROOT/rel; p.parent.mkdir(parents=True, exist_ok=True); p.write_text(text, encoding="utf-8")

write('bot-core/src/main/kotlin/dev/pylarl/botcore/combat/RevengeWorldModel.kt', 'package dev.pylarl.botcore.combat\n\nimport dev.pylarl.botcore.vision.Vector2\nimport kotlin.math.round\n\nobject RevengeWorldModel {\n    const val TILE_SIZE_WORLD = 300f\n    const val WORLD_PER_CANONICAL_PX = 75f / 16f\n    const val DEFAULT_MOVE_SPEED_WORLD = 720f\n    const val SPEED_PAD = 1.35f\n    const val DEFAULT_BODY_RADIUS_WORLD = 60f\n    const val FALLBACK_PROJECTILE_SPEED_WORLD = 4000f\n    const val FLIGHT_CAP_SECONDS = 1.15f\n    const val MOTION_WATCH_NANOS = 80_000_000L\n    const val MOTION_STRIDE_WORLD = 40f\n    const val STICKY_BUFFER_WORLD = 200f\n    const val MOVE_REACH_WORLD = 600f\n    const val DIRECTION_COUNT = 48\n    const val DIRECTION_LOCK_NANOS = 130_000_000L\n    const val KEEP_BAND = 120f\n    const val MOMENTUM = 100f\n\n    fun canonicalPxToWorld(value: Float): Float = value * WORLD_PER_CANONICAL_PX\n    fun worldToCanonicalPx(value: Float): Float = value / WORLD_PER_CANONICAL_PX\n    fun vectorToWorld(value: Vector2): Vector2 = value * WORLD_PER_CANONICAL_PX\n    fun vectorToCanonical(value: Vector2): Vector2 = value * (1f / WORLD_PER_CANONICAL_PX)\n    fun roundSkillRangeFromCanonical(value: Float): Float = round(canonicalPxToWorld(value) / 100f) * 100f\n}\n')
write('bot-core/src/main/kotlin/dev/pylarl/botcore/combat/BrawlerCombatProfile.kt', 'package dev.pylarl.botcore.combat\n\nenum class CombatRangeClass { CLOSE, MID, LONG, ULTRA_LONG }\nenum class AttackStyle { MELEE, DASH, SHOTGUN, LINEAR, BURST, SNIPER, THROWER, SPRAY, WAVE, BOOMERANG }\n\ndata class BrawlerCombatProfile(\n    val key: String,\n    val displayName: String,\n    val safeRange: Float,\n    val attackRange: Float,\n    val projectileSpeedPxPerSecond: Float,\n    val fireDelaySeconds: Float,\n    val ignoreWallsForAttacks: Boolean = false,\n    val leadPercent: Int = 65,\n    val attackStyle: AttackStyle = AttackStyle.LINEAR,\n    val moveSpeedWorld: Float = RevengeWorldModel.DEFAULT_MOVE_SPEED_WORLD,\n    val projectileRadiusWorld: Float = 120f,\n) {\n    val safeRangeWorld: Float = RevengeWorldModel.roundSkillRangeFromCanonical(safeRange)\n    val attackRangeWorld: Float = RevengeWorldModel.roundSkillRangeFromCanonical(attackRange)\n    val projectileSpeedWorldPerSecond: Float = projectileSpeedPxPerSecond * RevengeWorldModel.WORLD_PER_CANONICAL_PX\n    val rangeClass: CombatRangeClass = when {\n        attackRangeWorld <= 1200f -> CombatRangeClass.CLOSE\n        attackRangeWorld <= 2100f -> CombatRangeClass.MID\n        attackRangeWorld <= 2700f -> CombatRangeClass.LONG\n        else -> CombatRangeClass.ULTRA_LONG\n    }\n    val preferredRangeWorld: Float = when (attackStyle) {\n        AttackStyle.MELEE, AttackStyle.DASH -> attackRangeWorld * 0.62f\n        AttackStyle.SHOTGUN -> attackRangeWorld * 0.58f\n        AttackStyle.SPRAY, AttackStyle.WAVE -> attackRangeWorld * 0.68f\n        AttackStyle.BURST, AttackStyle.LINEAR, AttackStyle.BOOMERANG -> attackRangeWorld * 0.72f\n        AttackStyle.THROWER -> attackRangeWorld * 0.78f\n        AttackStyle.SNIPER -> attackRangeWorld * 0.82f\n    }\n    val preferredRange: Float = RevengeWorldModel.worldToCanonicalPx(preferredRangeWorld)\n}\n\nobject BrawlerCombatProfiles {\n    private fun speed(style: AttackStyle): Float = when(style){\n        AttackStyle.MELEE,AttackStyle.DASH->0f\n        AttackStyle.THROWER->2600f\n        AttackStyle.SNIPER->4500f\n        AttackStyle.SPRAY,AttackStyle.WAVE->3500f\n        AttackStyle.BOOMERANG->3000f\n        else->RevengeWorldModel.FALLBACK_PROJECTILE_SPEED_WORLD\n    }\n    private fun radius(style:AttackStyle):Float=when(style){\n        AttackStyle.SHOTGUN,AttackStyle.SPRAY,AttackStyle.WAVE->260f\n        AttackStyle.THROWER->180f\n        AttackStyle.SNIPER->90f\n        AttackStyle.MELEE,AttackStyle.DASH->60f\n        else->130f\n    }\n    private fun delay(style:AttackStyle):Float=when(style){\n        AttackStyle.MELEE,AttackStyle.DASH->.03f\n        AttackStyle.SHOTGUN->.045f\n        AttackStyle.THROWER->.12f\n        AttackStyle.SNIPER->.08f\n        else->.06f\n    }\n    private fun p(key:String,name:String,safe:Float,attack:Float,style:AttackStyle=AttackStyle.LINEAR,lead:Int=65,ignoreWalls:Boolean=false,move:Float=RevengeWorldModel.DEFAULT_MOVE_SPEED_WORLD):BrawlerCombatProfile{\n        val ws=speed(style)\n        return BrawlerCombatProfile(key,name,safe,attack,if(ws<=0f)0f else RevengeWorldModel.worldToCanonicalPx(ws),delay(style),ignoreWalls,lead,style,move,radius(style))\n    }\n    private val profiles=listOf(\n        p("shelly","Shelly",301f,490f,AttackStyle.SHOTGUN,65),p("colt","Colt",324f,546f,AttackStyle.BURST,62),p("bull","Bull",210f,341f,AttackStyle.SHOTGUN,65,move=770f),p("brock","Brock",354f,576f,AttackStyle.SNIPER,70),p("rico","Rico",380f,618f,AttackStyle.BURST,68),p("spike","Spike",301f,490f,AttackStyle.LINEAR,65),p("barley","Barley",288f,469f,AttackStyle.THROWER,65,true),p("jessie","Jessie",354f,576f,AttackStyle.LINEAR,72),p("nita","Nita",236f,384f,AttackStyle.WAVE,65),p("dynamike","Dynamike",288f,469f,AttackStyle.THROWER,65,true),p("elprimo","El Primo",0f,192f,AttackStyle.MELEE,65,move=770f),p("mortis","Mortis",0f,170f,AttackStyle.DASH,65,move=820f),p("crow","Crow",341f,554f,AttackStyle.LINEAR,65,move=820f),p("poco","Poco",275f,448f,AttackStyle.WAVE,65),p("bo","Bo",341f,554f,AttackStyle.BURST,74),p("piper","Piper",393f,640f,AttackStyle.SNIPER,56),p("pam","Pam",354f,576f,AttackStyle.SPRAY,69),p("tara","Tara",315f,512f,AttackStyle.WAVE,65),p("darryl","Darryl",236f,384f,AttackStyle.SHOTGUN,65,move=770f),p("penny","Penny",315f,512f,AttackStyle.LINEAR,61),p("frank","Frank",236f,384f,AttackStyle.WAVE,65,move=650f),p("tick","Tick",341f,554f,AttackStyle.THROWER,65,true),p("leon","Leon",380f,618f,AttackStyle.BURST,65,move=820f),p("rosa","Rosa",0f,234f,AttackStyle.MELEE,65,move=770f),p("carl","Carl",328f,533f,AttackStyle.BOOMERANG,76),p("bibi","Bibi",0f,234f,AttackStyle.MELEE,65,move=820f),p("8bit","8-Bit",393f,640f,AttackStyle.BURST,70,move=580f),p("sandy","Sandy",236f,384f,AttackStyle.WAVE,65),p("bea","Bea",393f,640f,AttackStyle.SNIPER,56),p("emz","Emz",262f,426f,AttackStyle.SPRAY,65),p("mrp","Mr. P",275f,448f,AttackStyle.LINEAR,65),p("max","Max",328f,533f,AttackStyle.BURST,68,move=820f),p("jacky","Jacky",0f,213f,AttackStyle.MELEE,65,true),p("gale","Gale",328f,533f,AttackStyle.WAVE,68),p("nani","Nani",341f,554f,AttackStyle.SNIPER,98),p("sprout","Sprout",196f,320f,AttackStyle.THROWER,65,true),p("surge","Surge",200f,426f,AttackStyle.LINEAR,72),p("colette","Colette",341f,554f,AttackStyle.LINEAR,57),p("amber","Amber",328f,533f,AttackStyle.SPRAY,83),p("lou","Lou",367f,597f,AttackStyle.BURST,60),p("byron","Byron",393f,640f,AttackStyle.SNIPER,59),p("edgar","Edgar",0f,128f,AttackStyle.MELEE,65,move=820f),p("stu","Stu",301f,490f,AttackStyle.BURST,60,move=770f),p("belle","Belle",393f,640f,AttackStyle.SNIPER,56),p("squeak","Squeak",301f,490f,AttackStyle.THROWER,74),p("grom","Grom",301f,490f,AttackStyle.THROWER,65,true),p("buzz","Buzz",0f,170f,AttackStyle.MELEE,65,move=770f),p("griff","Griff",328f,533f,AttackStyle.BURST,68)\n    )\n    private val byKey=profiles.associateBy{it.key}\n    private val aliases=mapOf("8-bit" to "8bit","el_primo" to "elprimo","el primo" to "elprimo","mr_p" to "mrp","mr. p" to "mrp","jess" to "jessie","rick" to "rico","mj" to "pam","barrelbot" to "darryl","taro" to "tara")\n    val all:List<BrawlerCombatProfile> get()=profiles\n    val names:List<String> get()=profiles.map{it.key}\n    fun forName(name:String?):BrawlerCombatProfile{ val raw=name?.trim()?.lowercase().orEmpty(); val key=aliases[raw]?:raw; return byKey[key]?:byKey.getValue("shelly") }\n}\n')
write('bot-core/src/main/kotlin/dev/pylarl/botcore/decision/EnemyTracker.kt', 'package dev.pylarl.botcore.decision\nimport dev.pylarl.botcore.combat.RevengeWorldModel\nimport dev.pylarl.botcore.vision.Vector2\nimport kotlin.math.abs\nimport kotlin.math.sqrt\nclass EnemyTracker {\n    private var mark:Vector2?=null; private var markTs=0L; private var velocity=Vector2(0f,0f); private var stableMarks=0\n    fun update(targetRelativeWorld:Vector2?,timestampNanos:Long,ownVelocityWorld:Vector2=Vector2(0f,0f),targetGaitWorld:Float=RevengeWorldModel.DEFAULT_MOVE_SPEED_WORLD):Vector2{\n        if(targetRelativeWorld==null){reset();return velocity}\n        val old=mark\n        if(old==null||markTs<=0L){mark=targetRelativeWorld;markTs=timestampNanos;velocity=Vector2(0f,0f);return velocity}\n        val dtNanos=timestampNanos-markTs\n        if(dtNanos<=0L)return velocity\n        if(dtNanos>650_000_000L){mark=targetRelativeWorld;markTs=timestampNanos;velocity=Vector2(0f,0f);stableMarks=0;return velocity}\n        if(dtNanos<RevengeWorldModel.MOTION_WATCH_NANOS)return velocity\n        val dt=dtNanos/1_000_000_000f; val delta=targetRelativeWorld-old; val gone=delta.length(); mark=targetRelativeWorld; markTs=timestampNanos\n        if(gone<RevengeWorldModel.MOTION_STRIDE_WORLD){velocity=velocity*.55f;if(velocity.length()<35f)velocity=Vector2(0f,0f);stableMarks++;return velocity}\n        var raw=delta*(1f/dt)+ownVelocityWorld; val cap=targetGaitWorld.coerceAtLeast(300f)*RevengeWorldModel.SPEED_PAD; val speed=raw.length(); if(speed>cap)raw=raw*(cap/speed)\n        velocity=if(stableMarks==0)raw else velocity*.48f+raw*.52f; stableMarks++; return velocity\n    }\n    fun confidence():Float=(stableMarks/3f).coerceIn(0f,1f)\n    fun currentVelocity():Vector2=velocity\n    fun reset(){mark=null;markTs=0L;velocity=Vector2(0f,0f);stableMarks=0}\n    fun predictWorldPoint(targetRelativeWorld:Vector2,projectileSpeedWorld:Float,leadPercent:Int,targetRadiusWorld:Float,projectileRadiusWorld:Float,maxRangeWorld:Float):Vector2{\n        if(projectileSpeedWorld<=1f||confidence()<.50f||velocity.length()<20f)return targetRelativeWorld\n        val scale=leadPercent.coerceIn(0,120)/100f; var point=targetRelativeWorld; var flight=(targetRelativeWorld.length()/projectileSpeedWorld).coerceIn(0f,RevengeWorldModel.FLIGHT_CAP_SECONDS)\n        val pocket=targetRadiusWorld.coerceAtLeast(0f)+projectileRadiusWorld.coerceAtLeast(0f); if(velocity.length()*flight<=pocket)return targetRelativeWorld\n        repeat(3){flight=(point.length()/projectileSpeedWorld).coerceIn(0f,RevengeWorldModel.FLIGHT_CAP_SECONDS);point=targetRelativeWorld+velocity*(flight*scale)}\n        if(maxRangeWorld>0f){val max=maxRangeWorld+targetRadiusWorld;val d=point.length();if(d>max&&d>1f)point=point*(max/d)}\n        return point\n    }\n    companion object {\n        data class Intercept(val point:Vector2,val flightSeconds:Float)\n        fun predictIntercept(shooter:Vector2,target:Vector2,targetVelocity:Vector2,projectileSpeedPxPerSecond:Float,fireDelaySeconds:Float=0f,leadScale:Float=1f):Intercept{\n            if(projectileSpeedPxPerSecond<=1f)return Intercept(target,0f);val r=target-shooter;val v=targetVelocity;val s=projectileSpeedPxPerSecond;val a=v.x*v.x+v.y*v.y-s*s;val b=2f*(r.x*v.x+r.y*v.y);val c=r.x*r.x+r.y*r.y\n            val t=when{abs(a)<1e-5f->if(abs(b)<1e-5f)0f else(-c/b).coerceAtLeast(0f);else->{val d=b*b-4f*a*c;if(d<0f)0f else{val q=sqrt(d);listOf((-b-q)/(2f*a),(-b+q)/(2f*a)).filter{it>0f}.minOrNull()?:0f}}}.coerceIn(0f,1.15f)\n            val total=(fireDelaySeconds+t*leadScale).coerceIn(0f,1.15f);return Intercept(target+v*total,t)\n        }\n        fun leadShotAngle(shooter:Vector2,target:Vector2,targetVelocity:Vector2,projectileSpeedPxPerSecond:Float,fireDelaySeconds:Float=0f,leadScale:Float=1f):Float=(predictIntercept(shooter,target,targetVelocity,projectileSpeedPxPerSecond,fireDelaySeconds,leadScale).point-shooter).angleDegrees()\n    }\n}\n')
write('bot-core/src/main/kotlin/dev/pylarl/botcore/decision/GameplayDecisionEngine.kt', 'package dev.pylarl.botcore.decision\nimport dev.pylarl.botcore.action.*\nimport dev.pylarl.botcore.combat.*\nimport dev.pylarl.botcore.config.BotConfig\nimport dev.pylarl.botcore.vision.*\nimport kotlin.math.*\nclass GameplayDecisionEngine {\n    private val tracker=EnemyTracker();private val wallEscape=WallEscape();private var lastAttack=Long.MIN_VALUE/2;private var lastSuper=0L;private var lockedTargetRelativeWorld:Vector2?=null;private var lastTargetSeenNanos=0L;private var lastMoveDir:Vector2?=null;private var lastMoveAngle:Float?=null;private var lastMoveNanos=0L;private var moveLockUntil=0L;private var lastMoveIndex=-1;private var strafeSide=1f;private var strafeFlipAt=0L\n    fun decide(observation:BotObservation,config:BotConfig):List<BotAction>{\n        FogAvoidance.action(observation.fogEscapeVector)?.let{rememberMove(it.angleDegrees,observation.timestampNanos);return listOf(it)}\n        wallEscape.update(observation,config)?.let{rememberMove(it.angleDegrees,observation.timestampNanos);return listOf(it)}\n        val player=observation.player?:run{clearTracking();return emptyList()};val pg=player.footPosition();val profile=BrawlerCombatProfiles.forName(observation.currentBrawler?:config.selectedBrawler);val target=selectTarget(pg,observation.enemies,observation.timestampNanos)\n        if(target==null){tracker.update(null,observation.timestampNanos);TeamFollow.action(player,observation.teammates,config)?.let{rememberMove(it.angleDegrees,observation.timestampNanos);return listOf(it)};val age=observation.timestampNanos-lastMoveNanos;val old=lastMoveAngle;return if(config.alwaysMove&&old!=null&&age in 0L..420_000_000L&&lastTargetSeenNanos>0L&&observation.timestampNanos-lastTargetSeenNanos<420_000_000L)listOf(MoveVector(old,145f,320L))else emptyList()}\n        val tg=target.footPosition();val relScreen=tg-pg;val relWorld=RevengeWorldModel.vectorToWorld(relScreen);val distanceWorld=relWorld.length();val blocked=blocked(pg,tg,observation.walls);val hittable=!blocked||profile.ignoreWallsForAttacks;lastTargetSeenNanos=observation.timestampNanos\n        val ownVelocity=currentOwnVelocity(profile,observation.timestampNanos);tracker.update(relWorld,observation.timestampNanos,ownVelocity,RevengeWorldModel.DEFAULT_MOVE_SPEED_WORLD);val actions=mutableListOf<BotAction>()\n        AbilityPolicy.superAction(observation.superReady,!blocked,RevengeWorldModel.worldToCanonicalPx(distanceWorld),observation.timestampNanos,lastSuper,config)?.let{actions+=it;lastSuper=observation.timestampNanos}\n        if(hittable&&config.aimedAttacks&&canAttackAtDistance(profile,distanceWorld)){val cooldown=(attackIntervalSeconds(profile,config)*1_000_000_000L).toLong();if(observation.timestampNanos-lastAttack>=cooldown){val aimWorld=if(config.smartAimEnabled&&config.leadShots&&profile.projectileSpeedWorldPerSecond>1f)tracker.predictWorldPoint(relWorld,profile.projectileSpeedWorldPerSecond,effectiveLead(profile),RevengeWorldModel.DEFAULT_BODY_RADIUS_WORLD,profile.projectileRadiusWorld,profile.attackRangeWorld)else relWorld;actions+=AttackVector(aimWorld.angleDegrees(),attackStickRadius(profile,config),attackSwipeDuration(profile,config));lastAttack=observation.timestampNanos}}\n        if(config.alwaysMove){val angle=chooseMovement(pg,relWorld,profile,observation);rememberMove(angle,observation.timestampNanos);actions+=MoveVector(angle,150f,320L)}\n        return actions\n    }\n    private fun selectTarget(player:Vector2,enemies:List<EntityBox>,now:Long):EntityBox?{if(enemies.isEmpty())return null;val old=lockedTargetRelativeWorld;if(old!=null&&lastTargetSeenNanos>0L){val dt=((now-lastTargetSeenNanos).coerceAtLeast(0L)/1_000_000_000f).coerceAtMost(.35f);val predicted=old+tracker.currentVelocity()*dt;val candidate=enemies.minByOrNull{RevengeWorldModel.vectorToWorld(it.footPosition()-player).distanceTo(predicted)};if(candidate!=null){val rel=RevengeWorldModel.vectorToWorld(candidate.footPosition()-player);val association=RevengeWorldModel.STICKY_BUFFER_WORLD+RevengeWorldModel.DEFAULT_BODY_RADIUS_WORLD;if(rel.distanceTo(predicted)<=association){lockedTargetRelativeWorld=rel;return candidate}};tracker.reset()};val fresh=enemies.minByOrNull{player.distanceTo(it.footPosition())}?:return null;lockedTargetRelativeWorld=RevengeWorldModel.vectorToWorld(fresh.footPosition()-player);tracker.reset();return fresh}\n    private fun canAttackAtDistance(p:BrawlerCombatProfile,d:Float):Boolean{val m=when(p.attackStyle){AttackStyle.MELEE,AttackStyle.DASH->.92f;AttackStyle.SHOTGUN->.84f;AttackStyle.SPRAY->.92f;else->1f};return d<=p.attackRangeWorld*m+RevengeWorldModel.DEFAULT_BODY_RADIUS_WORLD}\n    private fun effectiveLead(p:BrawlerCombatProfile):Int=when(p.attackStyle){AttackStyle.MELEE,AttackStyle.DASH->0;AttackStyle.SHOTGUN->min(p.leadPercent,28);AttackStyle.SPRAY,AttackStyle.WAVE->min(p.leadPercent,52);else->p.leadPercent}\n    private fun attackIntervalSeconds(p:BrawlerCombatProfile,c:BotConfig):Float=max(c.attackMinIntervalSeconds,when(p.attackStyle){AttackStyle.MELEE,AttackStyle.DASH->.23f;AttackStyle.SHOTGUN->.28f;AttackStyle.SPRAY,AttackStyle.BURST->.24f;AttackStyle.THROWER->.38f;AttackStyle.SNIPER->.36f;else->.30f})\n    private fun attackStickRadius(p:BrawlerCombatProfile,c:BotConfig):Float=when(p.attackStyle){AttackStyle.MELEE,AttackStyle.DASH->205f;AttackStyle.SHOTGUN->215f;else->c.aimSwipeRadius.coerceIn(220f,245f)}\n    private fun attackSwipeDuration(p:BrawlerCombatProfile,c:BotConfig):Long=when(p.attackStyle){AttackStyle.THROWER->90L;AttackStyle.SNIPER->72L;AttackStyle.MELEE,AttackStyle.DASH->55L;else->(c.aimSwipeDurationSeconds*1000f).roundToLong().coerceIn(58L,85L)}\n    private fun chooseMovement(player:Vector2,relativeTargetWorld:Vector2,profile:BrawlerCombatProfile,observation:BotObservation):Float{\n        val now=observation.timestampNanos;if(strafeFlipAt==0L){strafeSide=if(((now/100_000_000L)and 1L)==0L)1f else-1f;strafeFlipAt=now+1_450_000_000L}else if(now>=strafeFlipAt){strafeSide=-strafeSide;strafeFlipAt=now+1_450_000_000L}\n        val targetDist=relativeTargetWorld.length();val desired=profile.preferredRangeWorld;val beforeError=abs(targetDist-desired);val toward=normalized(relativeTargetWorld);val tangent=Vector2(-toward.y*strafeSide,toward.x*strafeSide);val stepWorld=min(RevengeWorldModel.MOVE_REACH_WORLD,profile.moveSpeedWorld*.35f);val stepPx=RevengeWorldModel.worldToCanonicalPx(stepWorld);val previous=lastMoveDir;val scores=FloatArray(RevengeWorldModel.DIRECTION_COUNT);var bestIdx=0;var bestScore=-Float.MAX_VALUE;val withinBand=abs(targetDist-desired)<max(150f,profile.attackRangeWorld*.09f)\n        for(i in 0 until RevengeWorldModel.DIRECTION_COUNT){val a=2.0*Math.PI*i/RevengeWorldModel.DIRECTION_COUNT;val d=Vector2(cos(a).toFloat(),sin(a).toFloat());val nextRel=relativeTargetWorld-d*stepWorld;var score=(beforeError-abs(nextRel.length()-desired))*1.8f;score+=(d.x*tangent.x+d.y*tangent.y)*if(withinBand)175f else 48f;if(previous!=null)score+=RevengeWorldModel.MOMENTUM*(d.x*previous.x+d.y*previous.y);val end=player+d*stepPx;if(hitsWall(player,end,observation.walls,RevengeWorldModel.worldToCanonicalPx(105f)))score-=9000f;if(end.x<70f||end.x>1850f||end.y<70f||end.y>1010f)score-=2600f;for(enemy in observation.enemies){val e=enemy.footPosition();val nd=RevengeWorldModel.canonicalPxToWorld(end.distanceTo(e));val safety=max(650f,profile.safeRangeWorld*.70f);if(nd<safety)score-=(safety-nd)*1.35f};scores[i]=score;if(score>bestScore){bestScore=score;bestIdx=i}}\n        var chosen=bestIdx;if(lastMoveIndex>=0&&now<moveLockUntil&&lastMoveIndex<scores.size){if(scores[lastMoveIndex]+RevengeWorldModel.KEEP_BAND>=scores[bestIdx])chosen=lastMoveIndex}else moveLockUntil=now+RevengeWorldModel.DIRECTION_LOCK_NANOS;lastMoveIndex=chosen;val angle=360f*chosen/RevengeWorldModel.DIRECTION_COUNT;val r=Math.toRadians(angle.toDouble());lastMoveDir=Vector2(cos(r).toFloat(),sin(r).toFloat());return angle\n    }\n    private fun currentOwnVelocity(profile:BrawlerCombatProfile,now:Long):Vector2{val d=lastMoveDir?:return Vector2(0f,0f);if(now-lastMoveNanos>550_000_000L)return Vector2(0f,0f);return d*profile.moveSpeedWorld}\n    private fun rememberMove(angle:Float,now:Long){lastMoveAngle=normalizeAngle(angle);lastMoveNanos=now;val r=Math.toRadians(angle.toDouble());lastMoveDir=Vector2(cos(r).toFloat(),sin(r).toFloat())}\n    private fun hitsWall(a:Vector2,b:Vector2,walls:List<EntityBox>,margin:Float):Boolean=walls.any{segmentIntersectsRect(a,b,it.left-margin,it.top-margin,it.right+margin,it.bottom+margin)}\n    private fun blocked(a:Vector2,b:Vector2,walls:List<EntityBox>):Boolean=walls.any{segmentIntersectsRect(a,b,it.left,it.top,it.right,it.bottom)}\n    private fun segmentIntersectsRect(a:Vector2,b:Vector2,left:Float,top:Float,right:Float,bottom:Float):Boolean{var t0=0f;var t1=1f;val dx=b.x-a.x;val dy=b.y-a.y;fun clip(p:Float,q:Float):Boolean{if(abs(p)<1e-6f)return q>=0f;val r=q/p;if(p<0f){if(r>t1)return false;if(r>t0)t0=r}else{if(r<t0)return false;if(r<t1)t1=r};return true};return clip(-dx,a.x-left)&&clip(dx,right-a.x)&&clip(-dy,a.y-top)&&clip(dy,bottom-a.y)}\n    private fun normalized(v:Vector2):Vector2{val l=v.length();return if(l<1e-4f)Vector2(0f,0f)else v*(1f/l)}\n    private fun normalizeAngle(v:Float):Float=((v%360f)+360f)%360f\n    private fun clearTracking(){tracker.reset();lockedTargetRelativeWorld=null;lastTargetSeenNanos=0L;lastMoveDir=null;lastMoveAngle=null;lastMoveNanos=0L;lastMoveIndex=-1;moveLockUntil=0L}\n}\n')
p=ROOT/'bot-core/src/main/kotlin/dev/pylarl/botcore/config/BotConfig.kt'
s=p.read_text()
if 'val selectedBrawler:' not in s: s=s.replace('    val debugOverlay: Boolean = false,\n','    val debugOverlay: Boolean = false,\n    val selectedBrawler: String = "shelly",\n')
p.write_text(s)
print('Applied REvengeBS world-coordinate combat v4')